<script lang="ts">
  import { jsonStore } from "@slop/svelte";
  import Check from "@lucide/svelte/icons/check"; import Pause from "@lucide/svelte/icons/pause"; import Play from "@lucide/svelte/icons/play"; import Plus from "@lucide/svelte/icons/plus"; import RotateCcw from "@lucide/svelte/icons/rotate-ccw";
  type Ingredient={id:number;text:string;checked:boolean};type Step={id:number;text:string};type Recipe={title:string;subtitle:string;servings:number;minutes:number;ingredients:Ingredient[];steps:Step[];nextID:number};
  const recipe=jsonStore<Recipe>("state",{title:"Recipe",subtitle:"",servings:2,minutes:20,ingredients:[],steps:[],nextID:1});
  let seconds=$state(recipe.current.minutes*60);let running=$state(false);let timer:ReturnType<typeof setInterval>|undefined;
  function setText(key:"title"|"subtitle",value:string):void{recipe.update(data=>{data[key]=value})}
  function setNumber(key:"servings"|"minutes",value:string):void{const number=Math.max(1,Number(value)||1);recipe.update(data=>{data[key]=number});if(key==="minutes"&&!running)seconds=number*60}
  function updateIngredient(id:number,value:string):void{recipe.update(data=>{const item=data.ingredients.find(entry=>entry.id===id);if(item)item.text=value})}
  function updateStep(id:number,value:string):void{recipe.update(data=>{const item=data.steps.find(entry=>entry.id===id);if(item)item.text=value})}
  function addIngredient():void{recipe.update(data=>{data.ingredients.push({id:data.nextID,text:"New ingredient",checked:false});data.nextID+=1})}
  function addStep():void{recipe.update(data=>{data.steps.push({id:data.nextID,text:"Describe the next step",});data.nextID+=1})}
  function toggle(id:number):void{recipe.update(data=>{const item=data.ingredients.find(entry=>entry.id===id);if(item)item.checked=!item.checked})}
  function start():void{running=!running;if(timer){clearInterval(timer);timer=undefined}if(running)timer=setInterval(()=>{if(seconds>0)seconds-=1;else{running=false;if(timer)clearInterval(timer)}},1000)}
  function reset():void{running=false;if(timer)clearInterval(timer);timer=undefined;seconds=recipe.current.minutes*60}
  const clock=$derived(`${String(Math.floor(seconds/60)).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`);
</script>
<main class="recipe" data-slop-selection="none"><header><p>RECIPE CARD</p><div><input aria-label="Recipe title" value={recipe.current.title} oninput={(e)=>setText("title",e.currentTarget.value)}/><span><input type="number" min="1" aria-label="Servings" value={recipe.current.servings} oninput={(e)=>setNumber("servings",e.currentTarget.value)}/> servings · <input type="number" min="1" aria-label="Minutes" value={recipe.current.minutes} oninput={(e)=>setNumber("minutes",e.currentTarget.value)}/> minutes</span></div><input class="subtitle" aria-label="Recipe subtitle" value={recipe.current.subtitle} oninput={(e)=>setText("subtitle",e.currentTarget.value)}/></header><section class="body"><aside><div class="section-title"><h2>Gather</h2><button onclick={addIngredient}><Plus/>Add</button></div><ol>{#each recipe.current.ingredients as item,index (item.id)}<li class:checked={item.checked}><button onclick={()=>toggle(item.id)} aria-label={item.checked?"Uncheck ingredient":"Check ingredient"}>{#if item.checked}<Check/>{:else}{String(index+1).padStart(2,"0")}{/if}</button><input aria-label={`Ingredient ${index+1}`} value={item.text} oninput={(e)=>updateIngredient(item.id,e.currentTarget.value)}/></li>{/each}</ol></aside><article><div class="section-title"><h2>Make</h2><button onclick={addStep}><Plus/>Add</button></div><ol>{#each recipe.current.steps as step,index (step.id)}<li><strong>{index+1}</strong><textarea aria-label={`Step ${index+1}`} value={step.text} oninput={(e)=>updateStep(step.id,e.currentTarget.value)}></textarea></li>{/each}</ol></article></section><footer><div class="timer"><span>KITCHEN TIMER</span><strong>{clock}</strong></div><div class="controls"><button onclick={reset} aria-label="Reset timer"><RotateCcw/></button><button class="play" onclick={start} aria-label={running?"Pause timer":"Start timer"}>{#if running}<Pause/>{:else}<Play/>{/if}</button></div><p>{recipe.current.ingredients.length} ingredients · {recipe.current.steps.length} steps</p></footer></main>
